const fs=require('fs'),assert=require('assert/strict');const origin='https://adaptiveenglish.vercel.app';
(async()=>{const cases=[{path:'/',expected:200},{path:'/auth/login',expected:200},{path:'/auth/register',expected:200},{path:'/teacher/assignments/create',expected:[302,307]},{path:'/api/teacher/generate-assignment',expected:405},{path:'/api/audio/play?pathname=invalid',expected:401},{path:'/api/audio/upload',expected:401,method:'POST',body:JSON.stringify({mimeType:'audio/wav',size:1000})},{path:'/api/audio/upload-token',expected:401,method:'POST',body:JSON.stringify({type:'blob.generate-client-token',payload:{pathname:'audio/controlled-qa/practice/12345678-1234-1234-1234-123456789abc.wav',clientPayload:null,multipart:false}})}];const results=await Promise.all(cases.map(async item=>{try{const res=await fetch(origin+item.path,{method:item.method||'GET',body:item.body,redirect:'manual',headers:item.body?{'Content-Type':'application/json'}:{},signal:AbortSignal.timeout(20000)});const body=await res.text();const allowed=Array.isArray(item.expected)?item.expected:[item.expected];const pass=allowed.includes(res.status);return{path:item.path,method:item.method||'GET',status:res.status,expected:item.expected,pass,location:res.headers.get('location'),registrationPreserved:item.path==='/auth/register'?body.includes('register-confirm-email')&&!body.includes('register-otp'):undefined};}catch(error){return{path:item.path,pass:false,error:error.name};}}));console.log(JSON.stringify({origin,results,scope:'Anonymous public HTTP smoke only; no DB writes, real accounts, AI requests or Blob uploads'},null,2));assert(results.every(r=>r.pass));assert(results.find(r=>r.path==='/auth/register').registrationPreserved);})().catch(error=>{console.error(error.message);process.exitCode=1;});
